// Categorise the ticket. Topic categories win over the generic complaint/general buckets:
// "مشكلة في الامتحان" is an exams ticket even though it also says "problem".
const triggerData = $input.first().json;
const rawMessage = String(triggerData.customer_message || triggerData.message || '').replace(/\s+/g, ' ').trim();
const message = rawMessage.toLowerCase().replace(/[إأآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه');

const topicKeywords = {
  exams: ['امتحان', 'اختبار', 'exam', 'test', 'seb', 'safe exam', 'quiz', 'نتيجه', 'result'],
  lms: ['lms', 'منصه', 'platform', 'e-learning', 'course access'],
  account: ['حساب', 'account', 'باسورد', 'كلمه السر', 'password', 'username', 'ايميل', 'البريد', 'email', 'الرقم القومي', 'national id', 'profile', 'بروفايل', 'الصوره'],
  certificates: ['شهاده', 'certificate', 'certification', 'accreditation'],
  enrollment: ['تسجيل', 'سجلت', 'اسجل', 'تقديم', 'اقدم', 'قبول', 'register', 'enroll', 'apply', 'admission', 'تحت المراجعه', 'المسار', 'التراك', 'تغيير المسار'],
  training: ['تدريب', 'محاضره', 'جروب', 'مدرب', 'المحافظه', 'training', 'session', 'instructor', 'coach', 'كوتش'],
  payments: ['مدفوعات', 'دفع', 'فلوس', 'رسوم', 'payment', 'fee', 'invoice', 'billing'],
  technical: ['error', 'bug', 'not working', 'مش شغال', 'عطل', 'تقني', 'technical'],
  partnership: ['شراكه', 'partner', 'partnership', 'collaboration', 'university', 'جامعه']
};
const complaintKeywords = ['شكوي', 'complaint', 'غاضب', 'زعلان', 'سيئه', 'سيء', 'angry', 'frustrated', 'unacceptable', 'terrible'];

let bestCategory = '';
let bestScore = 0;
for (const [cat, keywords] of Object.entries(topicKeywords)) {
  const score = keywords.filter(kw => message.includes(kw)).length;
  if (score > bestScore) { bestScore = score; bestCategory = cat; }
}
// An explicit complaint is routed to the complaints team whatever its topic.
if (/شكوي|complaint/.test(message)) {
  bestCategory = 'complaint';
  bestScore = Math.max(bestScore, 1);
} else if (!bestCategory) {
  const complaintScore = complaintKeywords.filter(kw => message.includes(kw)).length;
  bestCategory = complaintScore ? 'complaint' : 'general';
  bestScore = complaintScore;
}

// Title: the customer's own words, cut on a word boundary.
let title = rawMessage || 'Support request';
if (title.length > 80) {
  const cut = title.slice(0, 80);
  title = (cut.lastIndexOf(' ') > 40 ? cut.slice(0, cut.lastIndexOf(' ')) : cut) + '…';
}

return [{
  json: {
    ...triggerData,
    category_id: bestCategory,
    category_name: bestCategory,
    ticket_title: title,
    confidence: Math.min(1.0, 0.3 + bestScore * 0.2),
    keywords_matched: bestScore,
    customer_message: triggerData.customer_message || triggerData.message || ''
  }
}];

