/* ==========================================================================
   🐍 PYTHON ALTERNATIVE / البديل البرمجي بلغة بايثون لنفس المهمة
   --------------------------------------------------------------------------
   This node is documented in both Python and JavaScript.
   Below is the production-grade Python function equivalent:

def format_escalation_notice(ticket: dict, trigger_data: dict) -> dict:
    """
    تنسيق إشعار التصعيد مع رقم التذكرة ودرجة الأولوية.

    Formats a professional bilingual escalation notice with the
    generated ticket number and SLA priority level.

    Args:
        ticket: Row returned from the tickets INSERT.
        trigger_data: Original trigger data with locale.

    Returns:
        Dict with escalation status, ticket info, and reply.
    """
    locale = trigger_data.get("locale", "ar")
    is_ar = locale == "ar"
    ticket_num = ticket.get("ticket_number", "TICK-NEW")
    priority = ticket.get("priority", "high")

    if is_ar:
        priority_text = "عاجلة" if priority == "urgent" else "عالية"
        sla_text = "30 دقيقة" if priority == "urgent" else "ساعتين"
        reply = (
            f"أفهم إنك تحتاج مساعدة متخصصة، وحنا هنا عشانك. 👋\n\n"
            f"فتحنا لك تذكرة دعم بأولوية {priority_text} رقم **#{ticket_num}**.\n"
            f"ال متوقع نرد عليك خلال {sla_text}.\n\n"
            "فريق خدمة العملاء راح يراجع تفاصيل استفسارك ويتواصل معك في أقرب وقت."
        )
    else:
        sla_text = "30 minutes" if priority == "urgent" else "2 hours"
        reply = (
            f"I understand you need specialized help, and we're here for you. 👋\n\n"
            f"I've opened priority support ticket **#{ticket_num}** (Priority: {priority.upper()}).\n"
            f"Our team will respond within {sla_text}.\n\n"
            "A customer support representative is reviewing your request and will contact you shortly."
        )

    return {
        "status": "escalated",
        "intent_handled": "human_escalation",
        "ticket_number": ticket_num,
        "priority": priority,
        "sla_due_at": ticket.get("sla_due_at"),
        "reply": reply,
    }


# ==============================================================================
# 12. WORKFLOW 05 — Return Log Confirmation
# Node: "Return Log Confirmation"
# Purpose: Simple confirmation return after all logging operations complete.
# ==============================================================================
   ========================================================================== */

/* === ACTIVE JAVASCRIPT IMPLEMENTATION === */
const ticket = $('Create SLA Ticket in Postgres').first()?.json || {};
const trigger = $('Execute Workflow Trigger').first()?.json || {};
const locale = trigger.locale || 'ar';
const isAr = locale === 'ar';
const ticketNum = ticket.ticket_number || 'TICK-NEW';
const priority = ticket.priority || 'high';

let reply = '';
if (isAr) {
  reply = `تم استلام طلبك وتصعيده إلى الفريق المختص. تم فتح تذكرة دعم ذات أولوية برقم **#${ticketNum}** (درجة الأولوية: ${priority === 'urgent' ? 'عاجلة' : 'عالية'}).\nيقوم أحد مسؤولي خدمة العملاء بمراجعة تفاصيل استفسارك حالياً وسيتواصل معك مباشرة.`;
} else {
  reply = `I understand this requires specialist attention. I have opened priority support ticket **#${ticketNum}** for you (Priority: ${priority.toUpperCase()}).\nA customer support representative has been assigned and is reviewing your request to assist you directly.`;
}

return [{
  json: {
    status: 'escalated',
    intent_handled: 'human_escalation',
    request_id: trigger.request_id || null,
    execution_id: trigger.execution_id || null,
    workflow_id: 'CSWF000000000006',
    program: trigger.program || trigger.program_scope || null,
    llm_status: trigger.llm_status || 'failed',
    llm_latency_ms: trigger.llm_latency_ms ?? null,
    retrieval_latency_ms: trigger.retrieval_latency_ms ?? null,
    retrieved_count: trigger.retrieved_count || 0,
    source_ids: trigger.source_ids || [],
    source_urls: trigger.source_urls || [],
    grounded: false,
    guardrail_decision: trigger.guardrail_decision || 'human_escalation',
    fallback_reason: trigger.fallback_reason || null,
    ticket_number: ticketNum,
    priority: priority,
    sla_due_at: ticket.sla_due_at,
    reply: reply
  }
}];
